package io.zingg.duckdb.engine;
import io.zingg.duckdb.api.DuckException;
public final class SqlSafety {private SqlSafety(){} public static String predicate(String expression){if(expression==null||expression.isBlank())return "TRUE";String s=expression.trim();if(s.length()>4096||s.contains(";")||s.contains("--")||s.contains("/*")||s.contains("*/")||s.matches("(?is).*\\b(ATTACH|DETACH|COPY|INSTALL|LOAD|PRAGMA|CREATE|DROP|ALTER|INSERT|UPDATE|DELETE|EXPORT|IMPORT)\\b.*"))throw new DuckException("predicate contains disallowed SQL");return s;} public static String readOnlyQuery(String query){if(query==null||query.isBlank())throw new DuckException("query is empty");String s=query.trim();if(!s.matches("(?is)^(WITH\\b[\\s\\S]+|SELECT\\b[\\s\\S]+)$"))throw new DuckException("only SELECT/WITH queries are allowed");return predicate(s);}}
